     "t": "svg",
     "svg": "<svg viewBox=\"0 0 420 244\" role=\"img\" aria-label=\"Shopping cart class map\">\n<rect class=\"d-acc\" x=\"115\" y=\"6\" width=\"190\" height=\"48\" rx=\"6\"/><text class=\"d-b\" x=\"125\" y=\"26\">Cart</text><text class=\"d-s\" x=\"125\" y=\"44\">add, remove, checkout</text>\n<rect class=\"d-box\" x=\"20\" y=\"100\" width=\"190\" height=\"48\" rx=\"6\"/><text class=\"d-b\" x=\"30\" y=\"120\">Line</text><text class=\"d-s\" x=\"30\" y=\"138\">item, qty, total()</text>\n<path class=\"d-ar\" d=\"M115 30 L10 30 L10 124 L18 124\"/>\n<rect class=\"d-dashbox\" x=\"224\" y=\"100\" width=\"180\" height=\"48\" rx=\"6\"/><text class=\"d-b\" x=\"234\" y=\"120\">Discount</text><text class=\"d-s\" x=\"234\" y=\"138\">kind, value</text>\n<path class=\"d-ar\" d=\"M305 30 L412 30 L412 124 L406 124\"/>\n<rect class=\"d-dashbox\" x=\"224\" y=\"172\" width=\"180\" height=\"48\" rx=\"6\"/><text class=\"d-b\" x=\"234\" y=\"192\">Kind (enum)</text><text class=\"d-s\" x=\"234\" y=\"210\">PERCENT, FLAT</text>\n<path class=\"d-ar\" d=\"M305 30 L412 30 L412 196 L406 196\"/>\n<text class=\"d-a\" x=\"14\" y=\"22\">owns</text>\n<text class=\"d-a\" x=\"352\" y=\"22\">uses</text>\n</svg>",
     "alt": "Class map"
