     "solution": "class Splitwise\n- groups: Map<id, Group>  # every payer and participant is checked against one\n- expenses: Expense[]  # append-only record of what happened\n- ledger: Ledger  # req 2: the net owed per pair, so balances are one read\n+ create_group(group_id, members) -> void | error  # members for add_expense to check against\n+ add_expense(group_id, payer, amount_cents, split) -> Expense | error  # req 1\n+ settle(from_user, to_user, amount_cents) -> void | error  # req 3: a payment the other way\n+ balance(a, b) -> cents  (positive: a owes b)  # req 2: net between two users\n+ balances(user) -> Map<user, cents>  # req 2: one user against everyone\n\nclass Split\n- kind: SplitKind  (EQUAL, EXACT, PERCENT -> enum)  # which rule computes the shares\n- values: Map<user, number>  # who is in it, and cents or percent for them\n+ shares(amount_cents) -> Map<user, cents> | error  # req 1: always totals the amount\n\nclass Expense\n- group_id: string  # where it happened\n- payer: string  # who is owed the shares\n- amount_cents: int  # integer cents, so no float drift\n- shares: Map<user, cents>  # what each person owes the payer\n\nclass Group\n- members: Set<string>  # who an expense may involve\n+ has(user) -> bool  # add_expense checks every person\n\nclass Ledger\n- net: Map<(debtor, creditor), cents>  # one number per pair; settling is an entry the other way\n+ add(debtor, creditor, cents) -> void  # the one write, for expenses and payments\n+ owed(a, b) -> cents  # net of what b owes a\n+ balances(user) -> Map<user, cents>  # req 2: the non-zero nets for one user",
